theorem exists_transition [ProperSpace P] {L U : Set P}
    (hL : IsCompact L) (hU : IsOpen U) (hLU : L ⊆ U)
    (S : State L U) {ε : ℝ} (hε : 0 < ε) : Nonempty (Transition S ε)

